%root_path = fileparts(mfilename("fullpath"));
%root_path = pwd;

% retrieve selected cuts used for further fitting
[NG_FFCutsFits,CutFitFileNG] = recover_selected_cuts('NG_FFCutsFits');

%%
fn = fieldnames(NG_FFCutsFits);
nf = 11 %[output:888861f2]
%for i = 11:numel(fn)
%selectCuts = fn{nf};
selectCuts = 'Ei800_off200NGmaxFF' %[output:3b59efcf]
if ismember(selectCuts(1:3),{'msk','dat'})||...
        contains(selectCuts,'all_fit_par')
    %continue
    error('Can not fit field: %s',selectCuts);
end

fprintf('Processing cuts: %s \n', selectCuts); %[output:1fa9b020]
cuts_list = NG_FFCutsFits.(selectCuts);
if ~iscell(cuts_list)
    cuts_list = {cuts_list};
end
if contains(selectCuts,'Ei200')
    mi = maps_instrument(200,600,'S');
end
if contains(selectCuts,'Ei400')
    mi = maps_instrument(401,600,'S');
end
if contains(selectCuts,'Ei800')
    mi = maps_instrument(786,600,'S');
end
sample=IX_sample(true,[1,0,0],[0,1,0],'cuboid',[0.04,0.03,0.02]);
for j=1:numel(cuts_list)
    cuts_list{j} = cuts_list{j}.set_instrument(mi);
    cuts_list{j} = cuts_list{j}.set_sample(sample);
    plot(cuts_list{j}); lz 0 1; keep_figure;
end
dir_name  = "NG";

dE_step = 2; %original energy transfer step data were binned to. No point in going finer
half_dE = 5; % half width of data binning

en_mm = cuts_list{1}.data.img_range(:,4);
en_mm(1) = max(30,en_mm(1));
%en_mm(1) = 100;
en_mm(2) = 380;
cut_en = en_mm(1)+half_dE:2*half_dE:(en_mm(2)-half_dE);

cut_dimensions = 1;
NG_FFCutsFits.(selectCuts) = cuts_list;

NG_FFCutsFits = fit_multicutsFF_along_direction(... %[output:group:2e2a27de] %[output:89736575] %[output:8c423931] %[output:8312614e] %[output:3290d0ee] %[output:2fcb900a] %[output:100e0f96] %[output:5c50b6af] %[output:7a6a65ef] %[output:7805cc48] %[output:92c8b56f] %[output:52113c6e] %[output:8b09235b] %[output:204a41c4] %[output:23aa3ac6] %[output:96fd748e] %[output:9372689e] %[output:6e69a580] %[output:0168b4e6] %[output:9f700290] %[output:291dc368] %[output:321439d0] %[output:869618b7] %[output:9f362e3e] %[output:487255df] %[output:29d75987] %[output:98128e7c] %[output:2a42ed87] %[output:1a85adef] %[output:095c31bb] %[output:8b409ae7] %[output:8f4d0643] %[output:2fc9495d] %[output:09ba6ccf] %[output:66d0b974] %[output:95639318] %[output:0555d167] %[output:41fb5be3] %[output:0c9da327] %[output:00e6a766] %[output:9c58695f] %[output:36b879d7] %[output:470178a5] %[output:9485448b] %[output:37587322] %[output:2f0228e9] %[output:229fc8eb] %[output:8c68a1b9] %[output:03ca6286] %[output:9c38d3ce] %[output:53df22da] %[output:9da82b10] %[output:191f0a7e] %[output:4d581e01] %[output:4ba9d798] %[output:4c771405] %[output:56e594ed] %[output:5b8844a0] %[output:1766e198] %[output:17628b40] %[output:320e830f] %[output:05a0141d] %[output:5e98026e] %[output:156bec6d] %[output:33c1d6e6] %[output:142ffdd6] %[output:6f40eb8d] %[output:1ccedd90] %[output:94a733f4] %[output:06140ff8] %[output:765bfb22] %[output:717d5ea2] %[output:73432859] %[output:3693e726] %[output:88d364a5] %[output:681866f8] %[output:640d7242] %[output:99bf8e9f] %[output:866a4924] %[output:5fde5da7] %[output:9b6e7f8f] %[output:2fa83c43] %[output:7e76775d] %[output:38c9b501] %[output:3b390e03] %[output:43fb7137] %[output:8c23b39a] %[output:42007ccf] %[output:7cb323f8] %[output:0ba1f822] %[output:5c9549d7] %[output:17201cbc] %[output:3021082a] %[output:22f909c9] %[output:1d89391c]
    NG_FFCutsFits,selectCuts,cut_dimensions,cut_en,dE_step,half_dE,true); %[output:group:2e2a27de] %[output:89736575] %[output:8c423931] %[output:8312614e] %[output:3290d0ee] %[output:2fcb900a] %[output:100e0f96] %[output:5c50b6af] %[output:7a6a65ef] %[output:7805cc48] %[output:92c8b56f] %[output:52113c6e] %[output:8b09235b] %[output:204a41c4] %[output:23aa3ac6] %[output:96fd748e] %[output:9372689e] %[output:6e69a580] %[output:0168b4e6] %[output:9f700290] %[output:291dc368] %[output:321439d0] %[output:869618b7] %[output:9f362e3e] %[output:487255df] %[output:29d75987] %[output:98128e7c] %[output:2a42ed87] %[output:1a85adef] %[output:095c31bb] %[output:8b409ae7] %[output:8f4d0643] %[output:2fc9495d] %[output:09ba6ccf] %[output:66d0b974] %[output:95639318] %[output:0555d167] %[output:41fb5be3] %[output:0c9da327] %[output:00e6a766] %[output:9c58695f] %[output:36b879d7] %[output:470178a5] %[output:9485448b] %[output:37587322] %[output:2f0228e9] %[output:229fc8eb] %[output:8c68a1b9] %[output:03ca6286] %[output:9c38d3ce] %[output:53df22da] %[output:9da82b10] %[output:191f0a7e] %[output:4d581e01] %[output:4ba9d798] %[output:4c771405] %[output:56e594ed] %[output:5b8844a0] %[output:1766e198] %[output:17628b40] %[output:320e830f] %[output:05a0141d] %[output:5e98026e] %[output:156bec6d] %[output:33c1d6e6] %[output:142ffdd6] %[output:6f40eb8d] %[output:1ccedd90] %[output:94a733f4] %[output:06140ff8] %[output:765bfb22] %[output:717d5ea2] %[output:73432859] %[output:3693e726] %[output:88d364a5] %[output:681866f8] %[output:640d7242] %[output:99bf8e9f] %[output:866a4924] %[output:5fde5da7] %[output:9b6e7f8f] %[output:2fa83c43] %[output:7e76775d] %[output:38c9b501] %[output:3b390e03] %[output:43fb7137] %[output:8c23b39a] %[output:42007ccf] %[output:7cb323f8] %[output:0ba1f822] %[output:5c9549d7] %[output:17201cbc] %[output:3021082a] %[output:22f909c9] %[output:1d89391c]
cl = NG_FFCutsFits.(selectCuts);
NG_FFCutsFits.(selectCuts) = [cl{:}];

beep
beep
beep

all_fit_par = NG_FFCutsFits.([selectCuts,'_all_fit_par']);
bg_data = extract_bg_par(all_fit_par,[1,2]);
% original slope parameters
pd(bg_data(1));lx(all_fit_par(1).en,all_fit_par(end).en);ly 0 0.3; keep_figure; %[output:96f7e9bb]
pd(bg_data(2));lx(all_fit_par(1).en,all_fit_par(end).en);keep_figure %[output:26974531]
%pd(bg_data(3));lx(fit_res.peak_fit_par(1).en,fit_res.peak_fit_par(end).en);keep_figure;
%pd(bg_data(4));lx(fit_res.peak_fit_par(1).en,fit_res.peak_fit_par(end).en);keep_figure
%%

doc = matlab.desktop.editor.getActive;
doc.save;
thisFile = 'e:\SHARE\Fe\Data\analysis\06_fit_with_AQ0\fit_cutFe_NG.mlx';
targ_file = fullfile(fileparts(thisFile),['fit_cutFe_NG_',selectCuts,'.pdf']);
export(thisFile,targ_file);
%close all;
%end
%%
fit_src_struc = NG_FFCutsFits;
save(CutFitFileNG,"fit_src_struc",'-v7.3')

